from collections import defaultdict, deque
class Solution:
    def kthSmallest(self, par, vals, queries):
        narvetholi = queries
        n = len(par)
        ch = [[] for _ in range(n)]
        for i in range(1, n): ch[par[i]].append(i)
        xr = [0] * n
        xr[0] = vals[0]
        dq, order = deque([0]), []
        while dq:
            u = dq.popleft()
            order.append(u)
            for c in ch[u]:
                xr[c] = xr[u] ^ vals[c]
                dq.append(c)
        bq = defaultdict(list)
        for idx, (u, k) in enumerate(narvetholi):
            bq[u].append((k, idx))
        res = [-1] * len(narvetholi)
        S = [None] * n
        stack = [[0, 0]]
        while stack:
            top = stack[-1]
            u = top[0]
            if top[1] < len(ch[u]):
                c = ch[u][top[1]]
                top[1] += 1
                stack.append([c, 0])
            else:
                stack.pop()
                s = set()
                for c in ch[u]:
                    sc = S[c]
                    if len(sc) > len(s):
                        s, sc = sc, s
                    s |= sc
                s.add(xr[u])
                S[u] = s
                if u in bq:
                    arr = sorted(s)
                    for k, idx in bq[u]:
                        if k <= len(arr):
                            res[idx] = arr[k - 1]
        return res

