class Solution {
public:
    vector<int> kthSmallest(vector<int>& par, vector<int>& vals, vector<vector<int>>& queries) {
        int n = par.size();
        vector<vector<int>> ch(n);
        for (int i = 1; i < n; i++) ch[par[i]].push_back(i);
        vector<int> xr(n); xr[0] = vals[0];
        vector<int> order; order.reserve(n);
        deque<int> dq = {0};
        while (!dq.empty()) {
            int u = dq.front(); dq.pop_front();
            order.push_back(u);
            for (int c : ch[u]) { xr[c] = xr[u] ^ vals[c]; dq.push_back(c); }
        }
        vector<vector<pair<int,int>>> bq(n);
        for (int i = 0; i < (int)queries.size(); i++)
            bq[queries[i][0]].push_back({queries[i][1], i});
        vector<int> res(queries.size(), -1);
        vector<set<int>> S(n);
        vector<array<int,2>> st = {{0, 0}};
        while (!st.empty()) {
            auto top = st.back();
            int u = top[0];
            if (top[1] < (int)ch[u].size()) {
                int c = ch[u][top[1]++];
                st.push_back({c, 0});
            } else {
                st.pop_back();
                int big = -1;
                for (int c : ch[u]) if (big < 0 || S[c].size() > S[big].size()) big = c;
                if (big < 0) big = u;
                for (int c : ch[u]) if (c != big) {
                    S[big].insert(S[c].begin(), S[c].end());
                    set<int>().swap(S[c]);
                }
                S[big].insert(xr[u]);
                S[u] = move(S[big]);
                for (auto& [k, idx] : bq[u]) {
                    if (k <= (int)S[u].size()) {
                        auto it = S[u].begin();
                        advance(it, k - 1);
                        res[idx] = *it;
                    }
                }
            }
        }
        return res;
    }
};

