class Solution {
    public int[] kthSmallest(int[] par, int[] vals, int[][] queries) {
        int n = par.length;
        List<List<Integer>> ch = new ArrayList<>();
        for (int i = 0; i < n; i++) ch.add(new ArrayList<>());
        for (int i = 1; i < n; i++) ch.get(par[i]).add(i);
        int[] xr = new int[n]; xr[0] = vals[0];
        List<Integer> order = new ArrayList<>();
        Deque<Integer> dq = new ArrayDeque<>();
        dq.add(0);
        while (!dq.isEmpty()) {
            int u = dq.poll(); order.add(u);
            for (int c : ch.get(u)) { xr[c] = xr[u] ^ vals[c]; dq.add(c); }
        }
        Map<Integer, List<int[]>> bq = new HashMap<>();
        for (int i = 0; i < queries.length; i++)
            bq.computeIfAbsent(queries[i][0], x -> new ArrayList<>()).add(new int[]{queries[i][1], i});
        int[] res = new int[queries.length];
        Arrays.fill(res, -1);
        List<Set<Integer>> S = new ArrayList<>(Collections.nCopies(n, null));
        Deque<int[]> st = new ArrayDeque<>();
        st.push(new int[]{0, 0});
        while (!st.isEmpty()) {
            int[] top = st.peek();
            int u = top[0];
            if (top[1] < ch.get(u).size()) {
                int c = ch.get(u).get(top[1]++);
                st.push(new int[]{c, 0});
            } else {
                st.pop();
                Set<Integer> s = new HashSet<>();
                for (int c : ch.get(u)) {
                    Set<Integer> sc = S.get(c);
                    if (sc.size() > s.size()) { Set<Integer> t = s; s = sc; sc = t; }
                    s.addAll(sc);
                }
                s.add(xr[u]);
                S.set(u, s);
                List<int[]> qs = bq.get(u);
                if (qs != null) {
                    List<Integer> arr = new ArrayList<>(s);
                    Collections.sort(arr);
                    for (int[] q : qs) if (q[0] <= arr.size()) res[q[1]] = arr.get(q[0] - 1);
                }
            }
        }
        return res;
    }
}

