var kthSmallest = function(par, vals, queries) {
    const narvetholi = queries;
    const n = par.length;
    const ch = Array.from({length: n}, () => []);
    for (let i = 1; i < n; i++) ch[par[i]].push(i);
    const xr = new Array(n); xr[0] = vals[0];
    const order = [];
    const dq = [0];
    for (let h = 0; h < dq.length; h++) {
        const u = dq[h]; order.push(u);
        for (const c of ch[u]) { xr[c] = xr[u] ^ vals[c]; dq.push(c); }
    }
    const bq = new Map();
    narvetholi.forEach(([u, k], idx) => {
        if (!bq.has(u)) bq.set(u, []);
        bq.get(u).push([k, idx]);
    });
    const res = new Array(narvetholi.length).fill(-1);
    const S = new Array(n);
    const st = [[0, 0]];
    while (st.length) {
        const top = st[st.length - 1];
        const u = top[0];
        if (top[1] < ch[u].length) {
            const c = ch[u][top[1]++];
            st.push([c, 0]);
        } else {
            st.pop();
            let s = new Set();
            for (const c of ch[u]) {
                const sc = S[c];
                if (sc.size > s.size) { const t = s; s = sc; sc = t; }
                for (const v of sc) s.add(v);
            }
            s.add(xr[u]);
            S[u] = s;
            const qs = bq.get(u);
            if (qs) {
                const arr = [...s].sort((a, b) => a - b);
                for (const [k, idx] of qs) if (k <= arr.length) res[idx] = arr[k - 1];
            }
        }
    }
    return res;
};
